H,W=19,13
out=[[2]*W for _ in range(H)]
panels=[(1,1,9,[[1,0,1],[1,1,1],[0,1,0]]),
        (1,7,6,[[0,1,1],[0,1,1],[1,0,0]]),
        (7,1,3,[[1,0,1],[0,1,1],[0,1,0]]),
        (7,7,4,[[1,1,1],[0,1,0],[0,1,0]])]
for r,c,color,pat in panels:
    for i in range(5):
        for j in range(5): out[r+i][c+j]=color
    for i in range(3):
        for j in range(3):
            if pat[i][j]: out[r+1+i][c+1+j]=2
print('\n'.join(' '.join(map(str,row)) for row in out))
